package com.codepocket.ide

import org.json.JSONObject
import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.io.File
import java.security.MessageDigest

/** Responses are generated by the actual pinned Jedi backend, not handwritten success examples. */
internal object SemanticFixtures {
    val root:File get(){val cwd=File(System.getProperty("user.dir")!!);return if(cwd.name=="app")cwd.parentFile else cwd}
    private val data by lazy {
        JSONObject(File(root,"verification/python-semantic-integration-2026-10-26/semantic-fixtures.json").readText()).also{
            check(it.getBoolean("real_backend") && !it.getBoolean("android_execution"))
            val source=File(root,"app/src/main/python/semantics.py").readText().replace("\r\n","\n").toByteArray(Charsets.UTF_8)
            val digest=MessageDigest.getInstance("SHA-256").digest(source).joinToString(""){byte->"%02x".format(byte)}
            check(digest==it.getString("backend_sha256")){"Regenerate fixtures after changing the backend"}
        }
    }
    fun case(name:String)=data.getJSONObject("cases").getJSONObject(name)
    fun request(name:String):CompletionRequest{val f=case(name);val caret=f.getInt("caret");return CompletionRequest("internal:main.py",1,f.getString("code"),caret,caret,false)}
    fun result(name:String)=SemanticProtocol.decode(request(name),case(name).getString("response"),case(name).getString("mode"))
}
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34])
class SemanticProtocolTest {
    @Test fun actualListAndClassMembersHaveTheirRealKinds(){
        val list=SemanticFixtures.result("list");assertTrue(list.available);val completion=list.completion!!;assertEquals(SemanticProtocol.ENGINE,completion.source)
        assertEquals(CompletionKind.FUNCTION,completion.items.single{it.label=="append"}.kind)
        assertTrue(SemanticFixtures.result("instance").completion!!.items.any{it.label=="solve"})
        assertTrue(SemanticFixtures.result("json").completion!!.items.any{it.label=="loads"})
    }
    @Test fun exactMiddleTokenReplacementKeepsTheUnchangedPrefixAndUndoSource(){
        val request=SemanticFixtures.request("middle");val batch=SemanticFixtures.result("middle").completion!!
        val edit=batch.edit(request,batch.items.indexOfFirst{it.label=="upper"})!!
        assertEquals(request.code.indexOf("uppxx"),edit.start);assertEquals(request.code.length,edit.end)
        assertEquals("value='text'\nvalue.upper",request.code.replaceRange(edit.start,edit.end,edit.text))
        assertNull(batch.edit(request.copy(revision=2),0));assertNull(batch.edit(request.copy(document="other.py"),0))
    }
    @Test fun unicodeOffsetsAreAndroidUtf16AndDoNotDeleteEmoji(){
        val request=SemanticFixtures.request("unicode");val batch=SemanticFixtures.result("unicode").completion!!
        assertEquals(request.code.length-2,batch.start);assertEquals(request.code.length,batch.end)
        val edit=batch.edit(request,0)!!;assertTrue(request.code.replaceRange(edit.start,edit.end,edit.text).contains("😀中文"))
    }
    @Test fun actualSignaturesOverrideCuratedSameNameAndCarryCurrentParameter(){
        val signature=SemanticFixtures.result("signature").signature!!
        assertTrue(signature.reference.semantic);assertEquals(1,signature.active(0));assertEquals("combine",signature.reference.name)
        val shadowed=SemanticFixtures.result("shadowed").signature!!
        assertEquals(listOf("custom: str"),shadowed.reference.forms.single().parts);assertEquals(0,shadowed.active(0))
        assertNotEquals(BuiltinSignatures.find("print",false)!!.forms.first().parts,shadowed.reference.forms.single().parts)
    }
    @Test fun noResultIsDifferentFromBackendFailure(){
        val empty=SemanticFixtures.result("unknown");assertTrue(empty.available);assertNull(empty.completion)
        assertFalse(SemanticProtocol.decode(SemanticFixtures.request("list"),null,"complete").available)
        assertFalse(SemanticProtocol.decode(SemanticFixtures.request("list"),"not json","complete").available)
    }
    @Test fun malformedOrSplitSurrogateEditsAreRejected(){
        val request=SemanticFixtures.request("unicode");val raw=JSONObject(SemanticFixtures.case("unicode").getString("response"))
        for(start in listOf(-1,request.code.length+1,request.code.indexOf("😀")+1)){
            raw.put("start",start);assertFalse(SemanticProtocol.decode(request,raw.toString(),"complete").available)
        }
        raw.put("engine","untrusted");assertFalse(SemanticProtocol.decode(request,raw.toString(),"complete").available)
    }
    @Test fun clientPassesCurrentFileScopeAndNeverAnalyzesCppOrOversizedCode(){
        var payload:JSONObject?=null;var closed=false
        val transport=object:SemanticTransport{override fun analyze(value:String):String{payload=JSONObject(value);return SemanticFixtures.case("list").getString("response")};override fun close(){closed=true}}
        val client=PythonSemanticClient(transport);val request=SemanticFixtures.request("list")
        val result=client.analyze(request,SemanticLocation("/private/root","main.py",false),"complete")
        assertFalse(payload!!.getBoolean("project"));assertEquals(request.code,payload!!.getString("code"));assertTrue(result.completion!!.currentFileOnly)
        payload=null;assertFalse(client.analyze(request.copy(cpp=true),SemanticLocation("root","main.cpp",true),"complete").available);assertNull(payload)
        assertFalse(client.analyze(request.copy(code="x".repeat(45001)),SemanticLocation("root","main.py",true),"complete").available)
        client.close();assertTrue(closed)
    }
}
